-- ============================================================
-- Customer Shopping Behaviour Analysis
-- SQL business questions (PostgreSQL)
-- Table: customer (loaded from cleaned_customer_shopping_behavior.csv)
-- Author: Tharusha Fernando
-- ============================================================

-- ------------------------------------------------------------
-- Q1: What is the total revenue generated by male vs. female customers?
-- ------------------------------------------------------------
SELECT
    gender,
    SUM(purchase_amount) AS total_revenue,
    COUNT(*) AS num_transactions
FROM customer
GROUP BY gender
ORDER BY total_revenue DESC;


-- ------------------------------------------------------------
-- Q2: Which customers used a discount but still spent more than
--     the average purchase amount?
-- ------------------------------------------------------------
SELECT
    customer_id,
    purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer)
ORDER BY purchase_amount DESC;


-- ------------------------------------------------------------
-- Q3: Which are the top 5 products with the highest average review rating?
-- ------------------------------------------------------------
SELECT
    item_purchased,
    ROUND(AVG(review_rating::numeric), 2) AS avg_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY avg_product_rating DESC
LIMIT 5;


-- ------------------------------------------------------------
-- Q4: Compare the average purchase amounts between
--     Standard and Express shipping.
-- ------------------------------------------------------------
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type
ORDER BY avg_purchase DESC;


-- ------------------------------------------------------------
-- Q5: Do subscribed customers spend more?
--     Compare average spend and total revenue between
--     subscribers and non-subscribers.
-- ------------------------------------------------------------
SELECT
    subscription_status,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(purchase_amount), 2) AS avg_spend,
    ROUND(SUM(purchase_amount), 2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC;


-- ------------------------------------------------------------
-- Q6: Which 5 products have the highest percentage of purchases
--     with discounts applied?
-- ------------------------------------------------------------
SELECT
    item_purchased,
    ROUND(
        100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS discount_rate_pct
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate_pct DESC
LIMIT 5;


-- ------------------------------------------------------------
-- Q7: Segment customers into New, Returning and Loyal based on
--     their number of previous purchases, and show the count
--     of each segment.
-- ------------------------------------------------------------
WITH customer_type AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer
)
SELECT
    customer_segment,
    COUNT(*) AS num_customers
FROM customer_type
GROUP BY customer_segment
ORDER BY num_customers DESC;


-- ------------------------------------------------------------
-- Q8: What are the top 3 most purchased products within each category?
-- ------------------------------------------------------------
WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;


-- ------------------------------------------------------------
-- Q9: Are repeat buyers (more than 5 previous purchases) more
--     likely to subscribe than occasional buyers?
-- ------------------------------------------------------------
SELECT
    CASE
        WHEN previous_purchases > 5 THEN 'Repeat Buyer'
        ELSE 'Occasional Buyer'
    END AS buyer_type,
    subscription_status,
    COUNT(*) AS num_customers,
    ROUND(
        100.0 * COUNT(*) / SUM(COUNT(*)) OVER (
            PARTITION BY CASE
                WHEN previous_purchases > 5 THEN 'Repeat Buyer'
                ELSE 'Occasional Buyer'
            END
        ),
        2
    ) AS pct_within_group
FROM customer
GROUP BY buyer_type, subscription_status
ORDER BY buyer_type, subscription_status;


-- ------------------------------------------------------------
-- Q10: What is the revenue contribution of each age group?
-- ------------------------------------------------------------
SELECT
    age_group,
    COUNT(*) AS num_customers,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase,
    ROUND(
        100.0 * SUM(purchase_amount) / (SELECT SUM(purchase_amount) FROM customer),
        2
    ) AS revenue_pct
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;
